static THPObjectPtr get_storage_obj(Backend backend, ScalarType dtype) {
  auto module_name = torch::utils::backend_to_string(backend);
  auto module_obj = THPObjectPtr(PyImport_ImportModule(module_name));
  if (!module_obj)
    throw python_error();

  auto storage_name = std::string(toString(dtype)) + "Storage";
  THPObjectPtr storage(
      PyObject_GetAttrString(module_obj.get(), storage_name.c_str()));
  TORCH_CHECK_TYPE(
      storage.get(), "couldn't find storage object ", storage_name);
  return storage;
}

static void set_default_storage_type(Backend backend, ScalarType dtype) {
  THPObjectPtr storage = get_storage_obj(backend, dtype);

  auto torch_module = THPObjectPtr(PyImport_ImportModule("torch"));
  if (!torch_module)
    throw python_error();

  if (PyObject_SetAttrString(torch_module.get(), "Storage", storage) != 0) {
    throw python_error();
  }
}

static void set_default_tensor_type(
    std::optional<Backend> backend,
    std::optional<ScalarType> dtype) {
  if (backend.has_value()) {
    TORCH_CHECK_TYPE(
        *backend != Backend::Undefined, "default type cannot be undefined");
    TORCH_CHECK_TYPE(
        !isSparse(*backend),
        "only dense types are supported as the default type");
  }
  if (dtype.has_value()) {
    TORCH_CHECK_TYPE(
        at::isFloatingType(*dtype),
        "only floating-point types are supported as the default type");
  }

  // Try setting default storage in python first as it's the only operation that
  // can fail
  set_default_storage_type(
      backend.value_or(default_backend),
      dtype.value_or(at::get_default_dtype_as_scalartype()));

  if (dtype.has_value()) {
    at::set_default_dtype(scalarTypeToTypeMeta(*dtype));
  }
  if (backend.has_value()) {
    default_backend = *backend;
  }
}

void py_set_default_dtype(PyObject* obj) {
  TORCH_CHECK_TYPE(
      THPDtype_Check(obj),
      "invalid dtype object: only floating-point types are supported as the default type");
  auto scalar_type = ((THPDtype*)obj)->scalar_type;
  set_default_tensor_type(/*backend=*/std::nullopt, scalar_type);
}

static PyObject* THPModule_setDefaultDtype(PyObject* _unused, PyObject* dtype) {
  HANDLE_TH_ERRORS
  torch::tensors::py_set_default_dtype(dtype);
  Py_RETURN_NONE;
  END_HANDLE_TH_ERRORS
}

static PyObject* THPModule_getDefaultDtype(PyObject* _unused, PyObject* arg) {
  HANDLE_TH_ERRORS
  auto scalar_type = torch::tensors::get_default_scalar_type();
  return Py_NewRef(torch::getTHPDtype(scalar_type));
  END_HANDLE_TH_ERRORS
}

// Returns the set of dtypes that are fully realized Python singletons: all
// floating/complex/integer/bool/float8/float4/bits types. Excludes quantized
// dtypes and the placeholder sub-byte int/uint types, matching the dtypes
// tracked in torch.utils._dtype_abbrs.
static PyObject* THPModule_getAllDtypes(PyObject* _unused, PyObject* noargs) {
  HANDLE_TH_ERRORS
#define DEFINE_SCALAR_TYPE(_1, n) at::ScalarType::n,
  auto all_scalar_types = {
      AT_FORALL_SCALAR_TYPES_WITH_COMPLEX_AND_QINTS(DEFINE_SCALAR_TYPE)};
#undef DEFINE_SCALAR_TYPE

  auto is_subbyte_dummy = [](at::ScalarType t) {
    switch (t) {
      case at::ScalarType::UInt1:
      case at::ScalarType::UInt2:
      case at::ScalarType::UInt3:
      case at::ScalarType::UInt4:
      case at::ScalarType::UInt5:
      case at::ScalarType::UInt6:
      case at::ScalarType::UInt7:
      case at::ScalarType::Int1:
      case at::ScalarType::Int2:
      case at::ScalarType::Int3:
      case at::ScalarType::Int4:
      case at::ScalarType::Int5:
      case at::ScalarType::Int6:
      case at::ScalarType::Int7:
        return true;
      default:
        return false;
    }
  };

  THPObjectPtr result(PyList_New(0));
  if (!result)
    throw python_error();
  for (auto scalar_type : all_scalar_types) {
    if (c10::isQIntType(scalar_type) || is_subbyte_dummy(scalar_type)) {
      continue;
    }
    auto* dtype = reinterpret_cast<PyObject*>(torch::getTHPDtype(scalar_type));
    if (PyList_Append(result.get(), dtype) < 0) {
      throw python_error();
    }
  }
  return result.release();
  END_HANDLE_TH_ERRORS
}

ScalarType get_default_scalar_type() {
  return get_default_dtype_as_scalartype();
}

